// 상태가 '대기중'인 첫 번째 행을 찾습니다
const 대기중행 = items.filter(item => item.json['상태'] === '대기중');

if (대기중행.length === 0) {
  // 오늘 발행할 키워드 없음
  return [{ json: { __발행없음: true } }];
}

const row = 대기중행[0].json;
return [{
  json: {
    __발행없음: false,
    메인키워드: row['메인 키워드'] || '',
    서브키워드: row['서브키워드'] || '',
    포함키워드: row['포함할 키워드'] || '',
    서브수: parseInt(row['서브키워드 수']) || 3
  }
}];

const d = items[0].json;
const keyword = d.메인키워드;
const subKeywords = d.서브키워드;
const includeKeywords = d.포함키워드;
const subCount = d.서브수;

// 슬러그 생성 (영문+날짜)
const today = new Date();
const dateStr = today.toISOString().split('T')[0];
const dateCompact = dateStr.replace(/-/g, '');
const slug = keyword
  .replace(/\s+/g, '-')
  .replace(/[^a-zA-Z0-9가-힣-]/g, '')
  .substring(0, 40) + '-' + dateCompact;

// GPT-4o 요청 본문 구성
const gptBody = {
  model: 'gpt-4o',
  max_tokens: 3000,
  temperature: 0.7,
  messages: [
    {
      role: 'system',
      content: '당신은 장례·상조 분야 SEO 전문 블로그 작가입니다. 가효상조(gahyo.co.kr)의 서비스(후불제, 투명한 가격, 전문 장례지도사)를 자연스럽게 소개하는 전문적이고 따뜻한 글을 작성합니다.'
    },
    {
      role: 'user',
      content: `아래 조건으로 SEO 최적화 블로그 글을 HTML 형식으로 작성해주세요.

[키워드 조건]
- 메인 키워드: ${keyword}
- 서브키워드: ${subKeywords}
- 반드시 포함할 단어: ${includeKeywords}
- 서브키워드 각각 ${subCount}회 이상 자연스럽게 포함

[작성 규칙]
1. 분량: 1,500자 이상
2. <h2> 소제목 3개 이상, <h3> 소제목도 활용
3. <p>, <ul>, <li> 태그 사용
4. <body>, <html>, <head> 태그 제외 — 순수 본문 HTML만 출력
5. 첫 번째 <p>에 메인 키워드 자연스럽게 포함
6. 가효상조 서비스 특징을 본문 중간에 1회 자연스럽게 언급
7. 마지막 소제목은 '마무리' 또는 정리 문단으로 마무리
8. 제목(<h1> 또는 <h2> 첫 번째) 포함`
    }
  ]
};

return [{
  json: {
    keyword, subKeywords, includeKeywords, subCount,
    slug, dateStr,
    gptBody
  }
}];

const gptResult = items[0].json;
const prevData = $('슬러그 생성 및 GPT 요청 준비').first().json;

// GPT가 생성한 HTML 본문
const htmlContent = gptResult.choices[0].message.content;

// 제목 추출 (첫 번째 h1 또는 h2)
const titleMatch = htmlContent.match(/<h[12][^>]*>([^<]+)<\/h[12]>/i);
const title = titleMatch
  ? titleMatch[1].replace(/<[^>]+>/g, '').trim()
  : prevData.keyword + ' 완벽 가이드';

// excerpt 추출 (첫 번째 p 태그 텍스트, 최대 150자)
const excerptMatch = htmlContent.match(/<p[^>]*>([\s\S]*?)<\/p>/i);
const rawExcerpt = excerptMatch
  ? excerptMatch[1].replace(/<[^>]+>/g, '').trim()
  : prevData.keyword + ' 관련 전문 정보를 안내해드립니다.';
const excerpt = rawExcerpt.substring(0, 150) + (rawExcerpt.length > 150 ? '...' : '');

// DALL-E 3 요청 본문 구성
const dalleBody = {
  model: 'dall-e-3',
  prompt: `평화롭고 전문적인 한국 장례 서비스 장면. 부드럽고 따뜻한 조명, 품위 있는 분위기. "${prevData.keyword}" 주제와 관련된 이미지. 국화꽃, 따뜻한 실내 분위기. 이미지 안에 텍스트나 글자 없음. 사진 현실적 스타일.`,
  size: '1792x1024',
  quality: 'standard',
  n: 1
};

return [{
  json: {
    title, excerpt,
    htmlContent,
    keyword: prevData.keyword,
    slug: prevData.slug,
    dateStr: prevData.dateStr,
    dalleBody
  }
}];

const dalleResult = items[0].json;
const parsedData = $('GPT 응답 파싱 및 DALL-E 요청 준비').first().json;

const imageUrl = dalleResult.data[0].url;

// Firestore REST API용 문서 형식
const firestoreDoc = {
  fields: {
    title: { stringValue: parsedData.title },
    slug: { stringValue: parsedData.slug },
    content: { stringValue: parsedData.htmlContent },
    excerpt: { stringValue: parsedData.excerpt },
    imageUrl: { stringValue: imageUrl },
    publishedAt: { timestampValue: new Date().toISOString() },
    category: { stringValue: '장례정보' },
    tags: {
      arrayValue: {
        values: [{ stringValue: parsedData.keyword }]
      }
    }
  }
};

return [{
  json: {
    firestoreDoc,
    keyword: parsedData.keyword,
    slug: parsedData.slug,
    dateStr: parsedData.dateStr
  }
}];
